function renderTools(){const q=$('#search').value;const type=$('#resource-type').value, category=$('#resource-category').value;$$('[data-provider]').forEach(b=>b.classList.toggle('selected',b.dataset.provider===selectedProvider));const target=$('#tool-grid');target.replaceChildren();const matches=filterCatalog(tutorials,q,selectedProvider,type,category);$('#search-results').textContent=matches.length+' recursos encontrados'+(q.trim()?' para “'+q.trim()+'”':'')+'. A busca começa em Todas; Multi-IA aparece sem duplicações. Use os filtros para refinar.';matches.forEach(t=>{const index=tutorials.indexOf(t);const card=document.createElement('article');card.className='tool-card';const badge=document.createElement('span');badge.className='badge';badge.textContent=t.product||t.provider;const h=document.createElement('h3');h.textContent=t.title;const p=document.createElement('p');p.textContent=t.type==='prompt'?t.prompt.slice(0,135)+(t.prompt.length>135?'…':''):t.description;card.append(badge);if(t.type==='prompt'||t.type==='official'){const label=document.createElement('div');label.className='category';label.textContent=t.category;const shortcut=document.createElement('span');shortcut.className='shortcut';shortcut.textContent=t.shortcut;card.append(label,h,shortcut,p);}else card.append(h,p);const actions=document.createElement('div');actions.className='card-actions';const read=document.createElement('button');read.className='text-button';read.textContent=t.type==='official'?'Como acessar e usar ↗':t.type==='prompt'?'Ver instrução ↗':'Ler tutorial ↗';read.onclick=()=>openTutorial(index);actions.append(read);if(t.type==='prompt'||t.type==='official'){const copy=document.createElement('button');copy.className='button secondary';copy.textContent=t.type==='official'?'Copiar comando':'Copiar atalho';copy.onclick=async()=>{const copied=await copyInstruction(t.shortcut,true);if(copied&&t.type==='official')toast('Comando copiado. Use somente em '+t.product+'.');if(!copied){openTutorial(index);$('#shortcut-text').focus();$('#shortcut-text').select();toast('Copie o atalho pelo menu do navegador.');}};actions.append(copy);}card.append(actions);target.append(card);});if(!target.children.length){const e=document.createElement('div');e.className='empty';e.textContent='Nenhum recurso encontrado. Tente outro tema, tipo ou palavra.';target.append(e);}}
