function openTutorial(index){
 const t=tutorials[index], general=t.type==='prompt', official=t.type==='official';
 $('#tutorial-provider').textContent=t.product||t.provider;
 $('#tutorial-title').textContent=general||official?t.shortcut+' — '+t.title:t.title;
 $('#prompt-detail').hidden=!general&&!official;$('#tutorial-steps').hidden=general;
 $('#prompt-target').hidden=!general;$('#official-source-wrap').hidden=!official;
 $('#prompt-text').parentElement.hidden=official;$('#copy-prompt-detail').hidden=official;
 if(general||official){
  $('#tutorial-intro').textContent=official?t.description:t.category+' • Instrução geral';
  $('#tutorial-steps').replaceChildren();$('#prompt-text').value=t.prompt||'';$('#shortcut-text').value=t.shortcut;
  $('#copy-shortcut-detail').textContent=official?'Copiar comando':'Copiar só o atalho';
  $('#copy-shortcut-detail').onclick=async()=>{if(await copyInstruction(t.shortcut,true)){if(official)toast('Comando copiado. Use somente em '+t.product+'.');}else{$('#shortcut-text').focus();$('#shortcut-text').select();toast('Copie pelo menu do navegador.');}};
  $('#copy-prompt-detail').onclick=async()=>{if(!await copyInstruction(t.prompt)){$('#prompt-text').focus();$('#prompt-text').select();toast('Copie pelo menu do navegador.');}};
  if(official){$('#tutorial-steps').replaceChildren(...t.guide.steps.map(s=>{const li=document.createElement('li');li.textContent=s;return li;}));$('#official-start-guide').href=t.guide.url;$('#tutorial-note').textContent='Onde usar: '+t.product+'. Requer acesso ao produto e uma versão com esse comando. Não presuma que funciona no chat comum ou em outro produto. Confira a fonte para requisitos e opções.';$('#official-source').href=t.source;$('#official-checked').textContent=' • Conferido em '+t.checked;$('#tutorial-action').textContent='Ver documentação do produto ↗';$('#tutorial-action').onclick=()=>window.open(t.source,'_blank','noopener,noreferrer');}
  else{$('#tutorial-note').textContent='Compatível como instrução de texto com ChatGPT, Claude e Gemini; os resultados variam. O atalho sozinho precisa ter seu significado compreendido na conversa. A instrução completa é mais clara. Não ativa recursos indisponíveis.';$('#tutorial-action').textContent='Abrir IA escolhida ↗';$('#tutorial-action').onclick=()=>window.open(providers[$('#prompt-target-provider').value].url,'_blank','noopener,noreferrer');}
 }else{
  $('#tutorial-intro').textContent=t.description;$('#tutorial-note').textContent=t.note;
  $('#tutorial-steps').replaceChildren(...t.steps.map(s=>{const li=document.createElement('li');li.textContent=s;return li;}));
  $('#tutorial-action').textContent='Experimentar no laboratório ↗';$('#tutorial-action').onclick=()=>{$('#tutorial').close();$('#review-provider').value=t.provider;show('laboratorio');};
 }
 $('#tutorial').showModal();
}
