function projectDocument(exported=false){
 const doc=new DOMParser().parseFromString($('#code').value,'text/html');
 // References to our generated files are replaced for the sandbox preview.
 doc.querySelectorAll('link[rel="stylesheet"]').forEach(e=>{if(['style.css','./style.css'].includes(e.getAttribute('href')))e.remove();});
 doc.querySelectorAll('script[src]').forEach(e=>{if(['script.js','./script.js'].includes(e.getAttribute('src')))e.remove();});
 const style=doc.createElement(exported?'link':'style');
 if(exported){style.rel='stylesheet';style.setAttribute('href','style.css');}else{style.textContent=$('#css-code').value.replace(/<\/style/gi,'<\\/style');}
 doc.head.append(style);
 const json=$('#json-code').value;
 if(json.trim()){
  try{
   JSON.parse(json);
   doc.querySelectorAll('script#centralia-project-data[type="application/json"]').forEach(e=>e.remove());
   const data=doc.createElement('script');data.type='application/json';data.id='centralia-project-data';
   data.textContent=json.replace(/</g,'\\u003c');doc.body.append(data);
  }catch{/* Invalid JSON remains available for saving, exporting, and review. */}
 }
 const script=doc.createElement('script');
 if(exported)script.setAttribute('src','script.js');else script.textContent=$('#js-code').value.replace(/<\/script/gi,'<\\/script');
 doc.body.append(script);
 return '<!doctype html>\n'+doc.documentElement.outerHTML;
}
function validateJson(){
 const value=$('#json-code').value,status=$('#json-status');status.classList.remove('json-error');
 if(!value.trim()){status.textContent='JSON opcional: use esta aba para dados e configurações.';$('#json-code').removeAttribute('aria-invalid');return true;}
 try{JSON.parse(value);status.textContent='JSON válido. Será incluído como data.json na exportação.';$('#json-code').removeAttribute('aria-invalid');return true;}
 catch{status.textContent='JSON inválido: confira aspas duplas, vírgulas e chaves. Você pode salvar ou exportar para corrigir depois; esses dados não entram na prévia.';status.classList.add('json-error');$('#json-code').setAttribute('aria-invalid','true');return false;}
}
