$('#hero-create').onclick=createProject;$('#new-project').onclick=createProject;
$('#import-project').onclick=()=>{if(safeLeave())$('#file').click();};$('#file').onchange=async()=>{const f=$('#file').files[0];if(!f)return;if(f.size>2*1024*1024){toast('Escolha um HTML menor que 2 MB.');return;}if(!/\.html?$/i.test(f.name)){toast('Selecione um arquivo HTML.');return;}try{const code=await f.text();activeProject=null;$('#project-name').value=f.name.replace(/\.html?$/i,'').slice(0,70);$('#code').value=code;$('#css-code').value='';$('#js-code').value='';$('#json-code').value='';$('#issue').value='';dirty=true;updatePreview();show('laboratorio');toast('HTML importado. Confira a prévia e salve seu projeto.');}catch{toast('Não foi possível ler esse arquivo.');}finally{$('#file').value='';}};
function saveProject(){const name=$('#project-name').value.trim()||'Projeto sem nome';const code=$('#code').value;const id=activeProject||('p-'+Date.now()+'-'+Math.random().toString(36).slice(2,8));const item={id,name,code,css:$('#css-code').value,js:$('#js-code').value,json:$('#json-code').value,updated:new Date().toISOString()};const next=projects.filter(p=>p.id!==id);next.unshift(item);try{localStorage.setItem('centralia-projects',JSON.stringify(next));projects=next;activeProject=id;dirty=false;toast('Projeto salvo neste navegador.');return true;}catch{toast('Não foi possível salvar. Exporte o projeto para guardar seu trabalho.');return false;}}
$('#save').onclick=saveProject;$$('.code-editor').forEach(e=>e.oninput=()=>{dirty=true;$('#request-box').hidden=true;if(e.id==='json-code')validateJson();});$('#project-name').oninput=()=>dirty=true;$('#issue').oninput=()=>$('#request-box').hidden=true;$('#refresh').onclick=()=>{updatePreview();toast('Prévia atualizada.');};
function renderProjects(){const grid=$('#project-grid');grid.replaceChildren();if(!projects.length){grid.innerHTML='<div class="empty">Seu primeiro projeto ainda está por aqui.<br>Crie um site ou importe um arquivo HTML para começar.</div>';return;}for(const p of projects){const card=document.createElement('article');card.className='project-card';const badge=document.createElement('span');badge.className='badge';badge.textContent='SITE HTML';const h=document.createElement('h3');h.textContent=p.name;const info=document.createElement('p');const date=new Date(p.updated);info.textContent='Salvo neste navegador'+(!Number.isNaN(date.getTime())?' • '+date.toLocaleDateString('pt-BR'):'');const actions=document.createElement('div');actions.className='actions';const edit=document.createElement('button');edit.className='button secondary';edit.textContent='Abrir projeto ↗';edit.onclick=()=>{if(!safeLeave())return;activeProject=p.id;$('#project-name').value=p.name;$('#code').value=p.code;$('#css-code').value=p.css||'';$('#js-code').value=p.js||'';$('#json-code').value=typeof p.json==='string'?p.json:'';dirty=false;updatePreview();show('laboratorio');};const remove=document.createElement('button');remove.className='text-button';remove.textContent='Excluir';remove.onclick=()=>{if(!confirm('Excluir “'+p.name+'” deste navegador?'))return;const next=projects.filter(x=>x.id!==p.id);try{localStorage.setItem('centralia-projects',JSON.stringify(next));projects=next;if(activeProject===p.id){activeProject=null;dirty=true;}renderProjects();toast('Projeto excluído.');}catch{toast('Não foi possível excluir.');}};actions.append(edit,remove);card.append(badge,h,info,actions);grid.append(card);}}
function makeZip(files){
 const encoder=new TextEncoder(), parts=[], central=[];let offset=0;
 const table=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;table[n]=c>>>0;}
 function crc(bytes){let c=0xffffffff;for(const b of bytes)c=table[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0;}
 function header(size){const bytes=new Uint8Array(size);return {bytes,view:new DataView(bytes.buffer)};}
 for(const [name,text]of files){const data=encoder.encode(text), filename=encoder.encode(name), checksum=crc(data), h=header(30);h.view.setUint32(0,0x04034b50,true);h.view.setUint16(4,20,true);h.view.setUint16(6,0x0800,true);h.view.setUint16(12,33,true);h.view.setUint32(14,checksum,true);h.view.setUint32(18,data.length,true);h.view.setUint32(22,data.length,true);h.view.setUint16(26,filename.length,true);parts.push(h.bytes,filename,data);
 const c=header(46);c.view.setUint32(0,0x02014b50,true);c.view.setUint16(4,20,true);c.view.setUint16(6,20,true);c.view.setUint16(8,0x0800,true);c.view.setUint16(14,33,true);c.view.setUint32(16,checksum,true);c.view.setUint32(20,data.length,true);c.view.setUint32(24,data.length,true);c.view.setUint16(28,filename.length,true);c.view.setUint32(42,offset,true);central.push(c.bytes,filename);offset+=30+filename.length+data.length;}
 const centralSize=central.reduce((n,b)=>n+b.length,0), end=header(22);end.view.setUint32(0,0x06054b50,true);end.view.setUint16(8,files.length,true);end.view.setUint16(10,files.length,true);end.view.setUint32(12,centralSize,true);end.view.setUint32(16,offset,true);return new Blob([...parts,...central,end.bytes],{type:'application/zip'});
}
